/* Radius commission breakdown prototype. Plain JavaScript. Local demo data only.
 * Financial amounts stored in cents; allocations stored in basis points.
 * Production authorization, calculation and workflow must be server-owned.
 */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2}).format(n/100);
const pct=n=>(n/100).toLocaleString('en-US',{maximumFractionDigits:2});
function icon(name){let p=RADIUS_ICONS[name]||RADIUS_ICONS['info'];return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p.split('@').map(d=>`<path d="${d}"/>`).join('')}</svg>`;}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
function btn(label,action,variant='ghost',attrs='',glyph=''){return `<button type="button" class="rds-btn rds-btn--${variant}" data-action="${action}" ${attrs}>${glyph?icon(glyph):''}${label}</button>`;}
function badge(text,tone='secondary',dot=false){return `<span class="rds-badge rds-badge--${tone}${dot?' rds-badge--dot':''}">${esc(text)}</span>`;}
const original={version:1,price:50000000,role:'agent',selected:{side:'buying',agent:'ally'},theme:'light',sides:{listing:{name:'Listing side',rate:250,extra:0,confirmedLead:false,finalized:false,returned:false,agents:[{id:'ally',name:'Ally Mitchell',initials:'AM',allocation:10000,split:8000,confirmed:false}],deductions:[{id:'lcredit',kind:'credit',name:'Client credit',amount:50000,recipient:'Jordan Taylor'},{id:'lref',kind:'referral',name:'Referral',amount:100000,recipient:'West Coast Realty'}],fees:[{id:'lf1',name:'Transaction coordinator',amount:35000,payers:{ally:10000},recipient:'Harbor Transaction Services',payable:'external',mode:'equal',timing:'post',createdBy:'ally',tiers:[],scale:false},{id:'lf2',name:'E&O insurance',amount:15000,payers:{ally:10000},recipient:'Radius',payable:'radius',mode:'equal',timing:'post',createdBy:'team',tiers:[],scale:false}]},buying:{name:'Buying side',rate:100,extra:0,confirmedLead:false,finalized:false,returned:false,agents:[{id:'ally',name:'Ally Mitchell',initials:'AM',allocation:5000,split:8000,confirmed:false},{id:'jessica',name:'Jessica DeFerrari',initials:'JD',allocation:5000,split:8000,confirmed:false}],deductions:[{id:'bcredit',kind:'credit',name:'Client credit',amount:10000,recipient:'Jordan Taylor'},{id:'bref',kind:'referral',name:'Referral',amount:25000,recipient:'Bay Area Realty'}],fees:[{id:'bf1',name:'Transaction coordinator',amount:35000,payers:{ally:10000},recipient:'Harbor Transaction Services',payable:'external',mode:'equal',timing:'post',createdBy:'ally',tiers:[],scale:false},{id:'bf2',name:'E&O insurance',amount:15000,payers:{jessica:10000},recipient:'Radius',payable:'radius',mode:'equal',timing:'post',createdBy:'team',tiers:[],scale:false}]}},activity:[{actor:'Radius',text:'Commission breakdown created for 111 West Alma Avenue.',time:'2026-10-12T09:30:00.000Z'},{actor:'Team lead',text:'Added Jessica DeFerrari to the buying side. Set agent allocations to 50% each.',time:'2026-10-12T09:45:00.000Z'},{actor:'Ally Mitchell',text:'Added a $350.00 transaction coordinator fee on the buying side, payable to Harbor Transaction Services.',time:'2026-10-12T10:00:00.000Z'}]};
let state;try{state=JSON.parse(localStorage.getItem('radius-cda-web-v1'));}catch{}if(!state||state.version!==1)state=structuredClone(original);
let activeModal=null,lastFocus=null,toastTimer,modalDirty=false,localSave=true;
const side=()=>state.sides[state.selected.side];
const agent=()=>side().agents.find(a=>a.id===state.selected.agent);
const actor=()=>state.role==='agent'?'Ally Mitchell':state.role==='lead'?'Team lead':'Radius auditor';
const isLocked=s=>s.finalized;
const canEditSide=s=>!s.finalized;
const canEditFee=f=>!side().finalized&&(state.role!=='agent'||f.createdBy==='ally');
function apportion(total,people,key='allocation'){let remaining=total;return people.map((p,i)=>{const value=i===people.length-1?remaining:Math.round(total*p[key]/10000);remaining-=value;return value;});}
function feeCharges(f){const entries=Object.entries(f.payers),people=entries.map(([id,allocation])=>({id,allocation}));const vals=apportion(f.amount,people);return Object.fromEntries(people.map((p,i)=>[p.id,vals[i]]));}
function calc(s){const gross=Math.round(state.price*s.rate/10000)+s.extra;const deductions=s.deductions.reduce((a,f)=>a+f.amount,0);const basis=gross-deductions;const portions=apportion(basis,s.agents);const agents=s.agents.map((a,i)=>{const allocated=portions[i],pre=s.fees.filter(f=>f.timing==='pre').reduce((n,f)=>n+(feeCharges(f)[a.id]||0),0);const splitBasis=allocated-pre;const earned=Math.round(splitBasis*a.split/10000);const post=s.fees.filter(f=>f.timing!=='pre').reduce((n,f)=>n+(feeCharges(f)[a.id]||0),0);return {...a,allocated,pre,earned,team:splitBasis-earned,post,net:earned-post};});return {gross,deductions,basis,agents,net:agents.reduce((n,a)=>n+a.net,0),team:agents.reduce((n,a)=>n+a.team,0)-s.fees.reduce((n,f)=>n+(feeCharges(f).team||0),0),fees:s.fees.reduce((n,f)=>n+f.amount,0)};}
function store(){try{localStorage.setItem('radius-cda-web-v1',JSON.stringify(state));localSave=true;}catch{localSave=false;}renderSave();}
function renderSave(){const status=$('#savedState');if(status)status.innerHTML=icon(localSave?'check-check':'info')+(localSave?'Saved locally':'Session only');}
function log(text){state.activity.push({actor:actor(),text,time:new Date().toISOString()});}
function invalidate(s){s.agents.forEach(a=>a.confirmed=false);s.confirmedLead=false;s.returned=false;}
function saveChange(text,s=side()){invalidate(s);log(text);store();render();}
function currentStatus(s,a){if(s.finalized)return {text:'Finalized',tone:'green'};if(s.returned)return {text:'Returned for edits',tone:'red'};if(a)return a.confirmed?{text:'Confirmed',tone:'green'}:{text:a.id==='ally'&&state.role==='agent'?'Awaiting your confirmation':'Awaiting agent confirmation',tone:'amber'};if(s.confirmedLead)return{text:'Auditor review pending',tone:'blue'};if(s.agents.every(a=>a.confirmed))return{text:'Team lead confirmation pending',tone:'blue'};return{text:'Agent confirmation pending',tone:'amber'};}
function render(){document.documentElement.dataset.theme=state.theme;renderSave();renderOverview();renderDetail();const ac=$('#activityCount');if(ac)ac.textContent=state.activity.length;hydrateIcons();}
function renderOverview(){const total=Object.values(state.sides).reduce((n,s)=>n+calc(s).gross,0);$('#transactionMetrics').innerHTML=`<article class="rds-card overview-card"><div class="overview-card-label"><span data-icon="dollar-sign"></span><span>Total gross commission</span><span class="overview-info" title="Sum of the listing and buying side gross commissions. This amount is not edited here.">${icon('info')}</span></div><strong class="num">${money(total)}</strong></article><article class="rds-card overview-card"><div class="overview-card-label"><span data-icon="home"></span><span>Sale price</span></div><strong class="num">${money(state.price)}</strong></article>`;
$('#sideList').innerHTML=Object.entries(state.sides).map(([id,s])=>`<section class="side-section"><div class="side-head">${btn(s.name,'select-side','link',`class="side-heading" data-side="${id}" aria-current="${state.selected.side===id&&!state.selected.agent}"`)}<span class="side-award"><span class="award-text">Award ${pct(s.rate)}%${s.extra?' + '+money(s.extra):''}</span>${btn('','award','ghost',`data-side="${id}" class="award-edit rds-btn--icon rds-btn--sm" aria-label="Edit ${s.name.toLowerCase()} award" title="Edit award" ${s.finalized?'disabled':''}`,'pencil')}</span><span class="side-count">${s.agents.length} agent${s.agents.length>1?'s':''}</span><span class="num">${money(calc(s).gross)}</span></div>${s.agents.map(a=>{const selected=state.selected.side===id&&state.selected.agent===a.id;return `<div class="agent-sep" role="separator"></div><div class="agent-row ${selected?'selected':''}"><div class="agent-line"><span class="avatar">${a.initials}</span><div class="agent-name"><span class="agent-name-text">${esc(a.name)}</span><span class="agent-role">${a.id==='ally'?'Primary agent':'Co-agent'}${a.confirmed?' · Confirmed':''}</span></div></div><div class="agent-actions">${btn('Add fee','add-fee','ghost',`class="agent-link" data-side="${id}" data-agent="${a.id}" ${s.finalized||(state.role==='agent'&&a.id!=='ally')?'disabled':''}`,'plus')}${btn(selected?`${icon('check')} Viewing`:`View breakdown ${icon('arrow-right')}`,'select-agent','ghost',`class="view-agent agent-link ${selected?'selected-action':''}" data-side="${id}" data-agent="${a.id}" aria-label="View ${esc(a.name)} ${s.name.toLowerCase()} breakdown" aria-current="${selected}"`)}</div></div>`;}).join('')}${`<div class="agent-sep additional-agent-sep" role="separator"></div><button type="button" class="additional-agent" data-action="add-agent" data-side="${id}" ${s.finalized?'disabled':''} aria-label="Add additional agent to ${s.name}">${icon('plus')}<span>Additional agent</span></button>`}</section>`).join('');
// Merge extra class attributes emitted by helper is avoided by helper normalization below.
}
function row(label,amount,{sub='',actions='',total=false,subtotal=false}={}){const amt=String(amount??'');const tone=total||/net payout/i.test(String(label))?'reference-positive':/^[−-]/.test(amt)?'reference-negative':'';return `<div class="calc-row ${actions?'has-actions':''} ${total?'total-row':''} ${subtotal?'subtotal':''}"><div class="calc-label">${label}${sub?`<small>${sub}</small>`:''}</div><div class="amount-col"><span class="num ${tone}">${amount}</span>${actions?`<div class="row-actions">${actions}</div>`:''}</div></div>`;}
function referenceItem(label,sub,amount,tone=''){const amt=String(amount??'');const resolved=tone||(/net /i.test(label)?'reference-positive':/^[−-]/.test(amt)?'reference-negative':'');return `<div class="rds-item rds-item--flush reference-item"><span class="rds-item__content"><span class="rds-item__title">${esc(label)}</span>${sub?`<span class="rds-item__desc">${esc(sub)}</span>`:''}</span><span class="rds-item__actions"><strong class="num ${resolved}">${esc(amount)}</strong></span></div>`;}
function netPayoutCard(sub,amount){return `<div class="rds-card reference-net"><span class="reference-net-icon" aria-hidden="true">${icon('dollar-sign')}</span><div><strong>Net Payout</strong><small>${esc(sub)}</small></div><strong class="num reference-positive">${amount}</strong></div>`;}
function referencePlansAndTeam(){return `<div class="reference-section"><div class="section-title"><h3>Commission plans</h3></div><div class="breakdown-list reference-list"><div class="rds-item rds-item--flush reference-plan-row"><span class="rds-item__content"><span class="rds-item__title">Group → Team</span><span class="rds-item__desc">10% to team</span></span><select class="rds-select reference-plan-select" aria-label="Group to team commission plan"><option selected>Group post deduction</option><option>No post deduction</option></select></div><div class="rds-item rds-item--flush reference-plan-row"><span class="rds-item__content"><span class="rds-item__title">Agent → Group</span><span class="rds-item__desc">80/20 · $400 fee</span></span><select class="rds-select reference-plan-select" aria-label="Agent to group commission plan"><option selected>Base post deduction</option><option>Group post deduction</option><option>No post deduction</option></select></div></div></div><div class="section-sep" role="separator"></div><div class="breakdown-list">${row('Team Commission Basis','$9,000',{subtotal:true})}${row('Team Split 10%','$900')}${row('Radius Fee 5%','−$450')}</div>${netPayoutCard('Summit Realty Team','$450')}`;} 
function referenceGroupAndCda(s,a){const agentName=a?esc(a.name):'Agent Ally';return `<div class="reference-section"><div class="section-title"><h3>Best Agents Ever (Group)</h3></div><div class="reference-list">${referenceItem('20% Group Split from '+agentName,'','$1,620')}${referenceItem('Office Fee From '+agentName,'','$400')}${referenceItem('Photography Fee','Paid by Group','−$400','reference-negative')}</div>${netPayoutCard('Best Agents Ever','$1,620')}</div><div class="reference-section"><div class="section-title"><div><h3>CDA Preview</h3><p class="reference-caption">See payout amounts.</p></div></div><div class="reference-list"><div class="reference-subhead">${esc(s.name)}</div>${referenceItem('Agent '+agentName+' commission','80/20 plan','$4,980')}${referenceItem('Team Net Commission','After agent payouts','$450')}${referenceItem('Radius commission','Radius income per agent ICA','$450')}${referenceItem('Group commission','Group income after fees','$1,620')}</div></div>`;}
function editActions(action,id,label,removal=true,disabled=false){return btn('',''+action,'ghost',`class="rds-btn--icon rds-btn--sm" data-id="${id}" aria-label="Edit ${esc(label)}" title="Edit ${esc(label)}" ${disabled?'disabled':''}`,'pencil')+(removal?`<span class="row-action-sep" aria-hidden="true"></span>${btn('','remove','ghost',`class="rds-btn--icon rds-btn--sm row-action-remove" data-id="${id}" aria-label="Remove ${esc(label)}" title="Remove ${esc(label)}" ${disabled?'disabled':''}`,'x')}`:'');}
function chain(s){return `<div class="review-chain" aria-label="Confirmation progress"><span class="review-step ${s.agents.every(a=>a.confirmed)?'done':'current'}">${icon(s.agents.every(a=>a.confirmed)?'check-circle-2':'user')}Agents ${s.agents.filter(a=>a.confirmed).length}/${s.agents.length}</span>${icon('chevron-right')}<span class="review-step ${s.confirmedLead?'done':s.agents.every(a=>a.confirmed)?'current':''}">${icon(s.confirmedLead?'check':'users')}Team lead</span>${icon('chevron-right')}<span class="review-step ${s.finalized?'done':s.confirmedLead?'current':''}">${icon(s.finalized?'check':'file-text')}Radius review</span></div>`;}
function renderDetail(){const s=side(),a=agent(),c=calc(s),ca=a?c.agents.find(x=>x.id===a.id):null,st=currentStatus(s,a);const pageStatus=$('#pageStatus');if(pageStatus)pageStatus.innerHTML=badge(st.text,st.tone,true);$('#detailHead').innerHTML=`<div class="detail-titlegroup">${btn('','mobile-overview','ghost','class="rds-btn--icon mobile-overview-btn" aria-label="Show transaction outline"','arrow-left')}<span class="avatar">${a?a.initials:icon('building-2')}</span><div class="detail-title-row"><h2>${a?esc(a.name):s.name+' overview'}</h2><div class="detail-meta">${a?`${s.agents.length>1?`${btn(pct(a.allocation)+'% Allocation','allocation','link',`data-side="${state.selected.side}" ${s.finalized?'disabled':''}`)}`:''}`:`<span>Company Breakdown</span>${s.agents.length>1?`<span>·</span>${btn('Edit allocations','allocation','link',`data-side="${state.selected.side}" ${s.finalized?'disabled':''}`)}`:''}`}</div></div></div>`;
let html=s.returned?`<div class="rds-alert inline-alert">${icon('info')}<p><strong>Returned for edits</strong><br>${esc(s.returnReason||'Review the numbers and confirm again.')}</p></div>`:'';
const award=pct(s.rate)+'%'+(s.extra?' + '+money(s.extra):'');
const credits=s.deductions.filter(d=>d.kind==='credit');
const referrals=s.deductions.filter(d=>d.kind==='referral');
html+=`<div class="breakdown-list">${row('Award',award,{actions:editActions('award',state.selected.side,'award',false,s.finalized)})}${row('Gross commission',money(c.gross))}${credits.map(d=>row('Credit',`−${money(d.amount)}`,{actions:editActions('edit-deduction',d.id,d.name,true,s.finalized)})).join('')}${referrals.map(d=>row('Referral',`−${money(d.amount)}`,{actions:editActions('edit-deduction',d.id,d.name,true,s.finalized)})).join('')}${row('Gross after credits and referrals',money(c.basis),{subtotal:true})}</div>`;

if(a){html+=referencePlansAndTeam();html+=`<div class="section-sep" role="separator"></div><div class="breakdown-list">${row('Agent & Group commission basis','$8,100',{subtotal:true})}${row('Agent split',money(ca.allocated),{sub:'Share of '+money(c.basis)})}${row('Agent → Team',pct(a.split)+' / '+pct(10000-a.split),{sub:'Commission plan',actions:editActions('plan','plan','plan',false,s.finalized)})}${row('Team share','−'+money(ca.team),{sub:pct(10000-a.split)+'% of '+money(ca.allocated-ca.pre)})}${s.fees.filter(f=>feeCharges(f)[a.id]).map(f=>row(esc(f.name),'−'+money(feeCharges(f)[a.id]),{sub:'Payable to '+esc(f.recipient),actions:editActions('edit-fee',f.id,f.name,true,!canEditFee(f))})).join('')}</div>${netPayoutCard(a.name,money(ca.net))}`;}
else{html+=`<div class="breakdown-list">${c.agents.map(agentRow=>row(esc(agentRow.name),money(agentRow.net),{sub:pct(agentRow.split)+' / '+pct(10000-agentRow.split)+' plan',actions:btn('','select-agent','ghost',`class="rds-btn--icon rds-btn--sm" data-side="${state.selected.side}" data-agent="${agentRow.id}" aria-label="View ${esc(agentRow.name)} breakdown"`,'arrow-right')})).join('')}${row('Team share',money(c.team))}${row('Net payout',money(c.net),{total:true,sub:s.name})}</div>`;}
if(a)html+=referenceGroupAndCda(s,a);html+=chain(s);const last=state.activity.at(-1);html+=`<section class="activity-preview"><div class="section-title"><h3>Latest activity</h3>${btn('View all','activity','ghost','class="rds-btn--sm"','arrow-right')}</div><div class="activity-line"><span class="avatar">${esc(last.actor.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><div><p><strong>${esc(last.actor)}</strong> · <time>${formatTime(last.time)}</time></p><p>${esc(last.text)}</p></div></div></section>`;$('#detailBody').innerHTML=html;renderDock();}
function confirmState(){const s=side(),a=agent();if(s.finalized)return{allowed:false,label:'Finalized',reason:'This breakdown is locked.'};if(state.role==='agent'){if(!a)return{allowed:false,label:'Select your breakdown',reason:'Choose your agent row to confirm your commission.'};if(a.id!=='ally')return{allowed:false,label:'Awaiting agent',reason:`Only ${a.name} can confirm this agent breakdown.`};if(a.confirmed)return{allowed:false,label:'Confirmed',reason:'Your confirmation is saved. The team lead reviews next.'};return{allowed:true,label:'Confirm breakdown',reason:'Review your numbers before confirming.'};}if(state.role==='lead'){if(s.confirmedLead)return{allowed:false,label:'Confirmed',reason:'Waiting for Radius auditor review.'};if(!s.agents.every(a=>a.confirmed))return{allowed:false,label:'Awaiting agents',reason:`Waiting for ${s.agents.filter(a=>!a.confirmed).map(a=>a.name.split(' ')[0]).join(' and ')} to confirm.`};return{allowed:true,label:'Confirm breakdown',reason:'Confirm this side as team lead.'};}if(!s.confirmedLead)return{allowed:false,label:'Awaiting team lead',reason:'Agent and team lead confirmations are required.'};return{allowed:true,label:'Finalize breakdown',reason:'All participant confirmations are complete.'};}
function renderDock(){const s=side(),a=agent(),c=calc(s),cs=confirmState(),amount=state.role==='agent'&&a?c.agents.find(x=>x.id===a.id).net:state.role==='lead'?c.team:c.net;const scope=state.role==='agent'?(a?`${a.name.split(' ')[0]}'s net commission`:'Agent net commissions'):state.role==='lead'?'Team net commission':'Agent net commissions';const activityBtn=`<button type="button" class="rds-btn rds-btn--outline rds-btn--icon dock-activity" data-action="activity" aria-label="Comments & activity, ${state.activity.length}" title="Comments & activity">${icon('message-square')}<span class="rds-badge rds-badge--secondary" id="activityCount">${state.activity.length}</span></button>`;$('#confirmDock').innerHTML=`<div class="dock-money"><small>${scope}</small><strong class="num">${money(amount)}</strong></div><div class="dock-info"><strong>${s.name}${state.role!=='agent'?' · '+(state.role==='lead'?'Team lead':'Auditor'):''}</strong>${esc(cs.reason)}</div><div class="dock-actions">${activityBtn}${state.role==='auditor'?btn('Preview CDA','cda','outline','','file-text'):''}${cs.allowed?btn(cs.label,'confirm','default','','check'):cs.label==='Confirmed'||s.finalized?`<span class="dock-confirmed">${icon(s.finalized?'lock':'check-circle-2')}${cs.label}</span>`:btn(cs.label,'blocked','outline','','info')}${state.role==='auditor'&&!s.finalized&&(s.confirmedLead||s.agents.some(a=>a.confirmed))?btn('Return','return','ghost'):''}${state.role==='auditor'&&s.finalized?btn('Reopen','reopen','outline'):''}</div>`;}
function formatTime(t){return new Date(t).toLocaleString('en-IN',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function toast(message){clearTimeout(toastTimer);$('#toast').innerHTML=icon('check-circle-2')+`<span>${esc(message)}</span>`;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
// Normalize optional class additions without duplicate HTML attributes.
const baseBtn=btn;btn=function(label,action,variant='ghost',attrs='',glyph=''){const extras=[...attrs.matchAll(/class="([^"]*)"/g)].map(m=>m[1]).join(' ');attrs=attrs.replace(/class="[^"]*"/g,'');return baseBtn(label,action,variant,attrs,glyph).replace(`rds-btn--${variant}"`,`rds-btn--${variant} ${extras}"`);};
$('#railNav').innerHTML=[['home','Home'],['users','Clients'],['folder','Transactions'],['calendar','Calendar'],['file-text','Documents'],['dollar-sign','Commissions']].map(([i,t])=>`<button class="rcs-nav" data-active="${t==='Transactions'}" data-action="nav-info" data-label="${t}" aria-label="${t}" title="${t}">${icon(i)}</button>`).join('');
render();
function field(label,id,value='',type='text',hint=''){return `<div class="rds-field"><label class="rds-label" for="${id}">${label}</label><input class="rds-input" id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'step="0.01" inputmode="decimal"':''}>${hint?`<span class="rds-field__hint">${hint}</span>`:''}<span class="form-error" id="${id}-error"></span></div>`;}
function moneyField(label,id,value,hint=''){return `<div class="rds-field"><label class="rds-label" for="${id}">${label}</label><div class="rds-input-group"><span class="rds-input-group__addon">$</span><input id="${id}" name="${id}" type="number" step="0.01" min="0" inputmode="decimal" value="${value/100}"></div>${hint?`<span class="rds-field__hint">${hint}</span>`:''}<span class="form-error" id="${id}-error"></span></div>`;}
function selectField(label,id,options,value){return `<div class="rds-field"><label class="rds-label" for="${id}">${label}</label><select class="rds-select" id="${id}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function error(id,text){const el=$('#'+id);if(el){el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',id+'-error');el.focus();}const msg=$('#'+id+'-error');if(msg)msg.textContent=text;return false;}
