function footer(save='Save changes'){return btn('Cancel','close','outline')+btn(save,'modal-save','default');}
function selectContext(sideId,agentId){state.selected={side:sideId,agent:agentId||null};store();render();$('#detailScroll').scrollTop=0;$('.workspace').classList.remove('show-overview');$('#detailBody').classList.remove('view-transition');requestAnimationFrame(()=>$('#detailBody').classList.add('view-transition'));$('#selectionAnnouncement').textContent=`Viewing ${agentId?agent().name:side().name+' overview'}, ${side().name}.`;}
function allocationEditor(sideId,newAgent=null){const s=state.sides[sideId],draft=structuredClone(s.agents);if(s.finalized)return toast('This breakdown is finalized.');if(newAgent)draft.push(newAgent);modal({title:newAgent?'Allocate commission':'Edit agent allocations',description:`${s.name} · Allocations apply before each agent’s commission plan.`,wide:true,dirty:true,body:`${draft.map(a=>`<div class="allocation-edit-row"><span class="avatar">${a.initials}</span><div class="agent-name">${esc(a.name)}<span class="agent-role">${a.id==='ally'?'Primary agent':'Co-agent'}</span></div><div class="rds-input-group"><input type="number" min="0" max="100" step="0.01" id="alloc-${a.id}" data-alloc="${a.id}" value="${pct(a.allocation)}" aria-label="${esc(a.name)} allocation percentage"><span class="rds-input-group__addon">%</span></div></div>`).join('')}<div class="share-total" id="allocationTotal"><span>Total allocation</span><strong>100%</strong></div><div class="form-error" id="allocationError"></div><p class="demo-note" style="margin-top:16px">Changes update the amounts for every agent on this side. Existing confirmations will need to be reviewed again.</p>`,footer:btn('Split equally','equal-alloc','ghost')+footer('Save allocations'),onSave:()=>{const vals=draft.map(a=>Math.round(Number($('#alloc-'+a.id).value)*100));if(vals.some((n,i)=>!$('#alloc-'+draft[i].id).value||!Number.isFinite(n)||n<=0||n>10000)||vals.reduce((a,n)=>a+n,0)!==10000){$('#allocationError').textContent='Enter a share above 0% for each agent. Allocations must total exactly 100%.';return;}const old=s.agents.map(a=>`${a.name}: ${pct(a.allocation)}%`).join(', ');draft.forEach((a,i)=>a.allocation=vals[i]);s.agents=draft;closeModal(true);saveChange(`Changed ${s.name.toLowerCase()} allocations from ${old} to ${draft.map(a=>`${a.name}: ${pct(a.allocation)}%`).join(', ')}.`,s);toast('Allocations saved. Breakdown updated.');}});updateAllocTotal();}
function updateAllocTotal(){const inputs=$$('[data-alloc]');if(!inputs.length)return;const total=inputs.reduce((n,i)=>n+Math.round(Number(i.value)*100),0);$('#allocationTotal strong').textContent=pct(total)+'%';$('#allocationTotal').classList.toggle('invalid',total!==10000);}
function financeEditor(){if(Object.values(state.sides).some(s=>s.finalized))return toast('Reopen finalized breakdowns before changing sale price.');modal({title:'Edit sale price',description:'Both sides use this price to calculate their commission award.',dirty:true,body:moneyField('Sale price','salePrice',state.price),footer:footer('Save sale price'),onSave:()=>{const amount=Math.round(Number($('#salePrice').value)*100);if(!Number.isFinite(amount)||amount<=0)return error('salePrice','Enter a sale price greater than zero.');const old=state.price;state.price=amount;Object.values(state.sides).forEach(invalidate);closeModal(true);log(`Changed the sale price from ${money(old)} to ${money(amount)}. Both sides recalculated.`);store();render();toast('Sale price saved. Both sides updated.');}});}
