function updateFeeShares(){let sum=0;$$('[data-payer]').forEach(p=>{const input=$(`[data-share="${p.dataset.payer}"]`);input.parentElement.hidden=!p.checked;if(p.checked)sum+=Math.round(Number(input.value)*100);});const total=$('#feeShareTotal');if(total){total.querySelector('strong').textContent=pct(sum)+'%';total.classList.toggle('invalid',sum!==10000);}}
