document.addEventListener('input',e=>{if(e.target.closest('#overlayRoot'))modalDirty=true;if(e.target.matches('[data-alloc]'))updateAllocTotal();if(e.target.matches('[data-share]'))updateFeeShares();if(e.target.id==='payerSearch'){$$('[data-person]').forEach(row=>row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase()));}if(e.target.getAttribute('aria-invalid')==='true'){e.target.removeAttribute('aria-invalid');const msg=$('#'+e.target.id+'-error');if(msg)msg.textContent='';}});
document.addEventListener('change',e=>{if(e.target.matches('[data-payer]')){updateFeeShares();modalDirty=true;}if(e.target.id==='feePayable')$('#recipientField').hidden=e.target.value!=='external';if(e.target.id==='feeMode'){const selected=$$('[data-payer]:checked').map(x=>x.dataset.payer).filter(id=>id!=='team');const pool=selected.reduce((n,id)=>n+Math.round(Number($(`[data-share="${id}"]`).value)*100),0);let rest=pool;const weights=selected.map(id=>side().agents.find(a=>a.id===id)?.allocation||0),sum=weights.reduce((a,n)=>a+n,0);selected.forEach((id,i)=>{const n=i===selected.length-1?rest:Math.round(pool*(e.target.value==='allocation'&&sum?weights[i]/sum:1/selected.length));rest-=n;$(`[data-share="${id}"]`).value=pct(n);});updateFeeShares();}});
document.addEventListener('keydown',e=>{if(!activeModal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const focus=$$('#overlayRoot button:not(:disabled),#overlayRoot input:not(:disabled),#overlayRoot select,#overlayRoot textarea').filter(el=>el.getClientRects().length);if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('click',e=>{if(e.target.id==='modalOverlay'){closeModal();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const d=b.dataset,s=side();switch(d.action){case'select-agent':closeModal(true);selectContext(d.side,d.agent);break;case'select-side':closeModal(true);selectContext(d.side,null);break;case'allocation':allocationEditor(d.side||d.id||state.selected.side);break;case'equal-alloc':{const arr=$$('[data-alloc]');let rest=10000;arr.forEach((el,i)=>{const n=i===arr.length-1?rest:Math.floor(10000/arr.length);rest-=n;el.value=pct(n);});modalDirty=true;updateAllocTotal();break;}case'finance':financeEditor();break;case'award':awardEditor(d.side);break;case'plan':planEditor();break;case'add-credit':deductionEditor('credit');break;case'add-referral':deductionEditor('referral');break;case'edit-deduction':deductionEditor(null,d.id);break;case'add-fee':if(d.side)selectContext(d.side,d.agent);feeEditor(null,d.agent);break;case'edit-fee':feeEditor(d.id);break;case'add-agent':addAgentEditor(d.side);break;case'close':closeModal();break;case'modal-save':activeModal?.onSave?.();break;case'confirm':confirmEditor();break;case'blocked':blockedEditor();break;case'activity':activityEditor();break;case'add-comment':{const value=$('#newComment').value.trim();if(!value){$('#newComment').focus();return;}log(value);store();render();activityEditor();toast('Comment saved locally.');break;}case'theme':state.theme=state.theme==='light'?'dark':'light';store();render();break;case'settings':settingsEditor();break;case'reset':modal({title:'Reset this prototype?',description:'This removes only local sample edits and comments. The live transaction is not affected.',footer:btn('Cancel','close','outline')+btn('Reset sample data','confirm-reset','default')});break;case'confirm-reset':state=structuredClone(original);closeModal(true);store();render();toast('Sample data restored.');break;case'scale-toggle':{const on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(on));$('#tierArea').hidden=!on;if(on&&!$('#tierRows').children.length)addTier();modalDirty=true;break;}case'add-tier':addTier();modalDirty=true;break;case'remove-tier':b.closest('.tier-row').remove();modalDirty=true;break;case'remove':{const f=s.fees.find(f=>f.id===d.id)||s.deductions.find(f=>f.id===d.id);if(!f||s.finalized)return;modal({title:`Remove ${esc(f.name.toLowerCase())}?`,description:`This removes ${money(f.amount)} from the ${s.name.toLowerCase()} and recalculates the breakdown.`,footer:btn('Cancel','close','outline')+btn('Remove','modal-save','destructive'),onSave:()=>{s.fees=s.fees.filter(f=>f.id!==d.id);s.deductions=s.deductions.filter(f=>f.id!==d.id);closeModal(true);saveChange(`Removed ${f.name}, ${money(f.amount)}, from the ${s.name.toLowerCase()}.`);toast('Removed. Breakdown updated.');}});break;}case'cda':cdaEditor();break;case'print':window.print();break;case'return':returnEditor(false);break;case'reopen':returnEditor(true);break;case'mobile-overview':$('.workspace').classList.add('show-overview');break;case'mel':modal({title:'Mel Copilot',description:'Mel stays accessible in the navigation, without covering the confirmation bar.',body:'<p class="demo-note">AI chat is not connected in this standalone prototype. Your commission edits and confirmations remain local.</p>',footer:btn('Back to breakdown','close','default')});break;case'transaction':modal({title:'Transaction context',description:'111 West Alma Avenue · San Jose, CA 95110',body:`<div class="simple-rows">${row('Sale price',money(state.price))}${row('Closing date','Oct 30, 2026')}${row('Transaction type','Sale')}</div><p class="demo-note">The transaction route is outside this standalone prototype.</p>`,footer:btn('Back to breakdown','close','default')});break;case'nav-info':toast(`${d.label} is outside this commission prototype.`);break;}});
